// Repro for bucket A (data_byte_fail.log): data bits must leave LSB first.
// Checks only the eight data bits of each frame.
`timescale 1ns / 1ps
module tb_uart_data_order;
    localparam integer CPB    = 8;
    localparam integer CLK_NS = 10;
    localparam integer BIT_NS = CPB * CLK_NS;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #(CLK_NS / 2) clk = ~clk;

    reg [8*64-1:0] nonce;
    integer        checks;
    integer        failures;
    reg            done = 1'b0;

    task finish_with_verdict;
        begin
            if (!done) begin
                done = 1'b1;
                $display("VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failures);
                $finish;
            end
        end
    endtask

    task check_byte(input [7:0] b);
        reg [7:0] rx;
        integer   i;
        begin
            @(negedge clk);
            data  = b;
            start = 1'b1;
            @(posedge clk);              // frame accepted at this edge (E0)
            @(negedge clk);              // E0 + CLK/2
            start = 1'b0;
            #(BIT_NS / 2);               // middle of the start bit, on a negedge
            for (i = 0; i < 8; i = i + 1) begin
                #(BIT_NS);               // middle of data bit i
                rx[i] = tx;
            end
            checks = checks + 1;
            if (rx !== b) begin
                failures = failures + 1;
                $display("FAIL data_order: sent %02h, line carried %02h when read LSB first", b, rx);
            end else
                $display("PASS data_order: %02h", b);
            wait (!busy);
            repeat (2 * CPB) @(negedge clk);
        end
    endtask

    initial begin
        checks   = 0;
        failures = 0;
        nonce    = "none";
        if (!$value$plusargs("NIRMAAN_NONCE=%s", nonce))
            if (!$value$plusargs("NONCE=%s", nonce))
                if (!$value$plusargs("nonce=%s", nonce))
                    nonce = "none";
        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (4) @(negedge clk);
        check_byte(8'h01);
        check_byte(8'h80);
        check_byte(8'hA5);
        check_byte(8'h3C);
        check_byte(8'hF0);
        check_byte(8'h12);
        finish_with_verdict;
    end

    initial begin
        #200000;
        checks   = checks + 1;
        failures = failures + 1;
        $display("FAIL data_order: watchdog timeout");
        finish_with_verdict;
    end
endmodule
=== END FILE ===
