// Repro for bucket B (parity_bit_fail.log): the parity bit must be even parity,
// i.e. equal to the XOR of the eight data bits. Checks only the parity bit.
`timescale 1ns / 1ps
module tb_uart_parity;
    localparam integer CPB    = 8;
    localparam integer CLK_NS = 10;
    localparam integer BIT_NS = CPB * CLK_NS;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #(CLK_NS / 2) clk = ~clk;

    reg [8*64-1:0] nonce;
    integer        checks;
    integer        failures;
    reg            done = 1'b0;

    task finish_with_verdict;
        begin
            if (!done) begin
                done = 1'b1;
                $display("VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failures);
                $finish;
            end
        end
    endtask

    task check_parity(input [7:0] b);
        reg par;
        begin
            @(negedge clk);
            data  = b;
            start = 1'b1;
            @(posedge clk);              // frame accepted at this edge (E0)
            @(negedge clk);              // E0 + CLK/2
            start = 1'b0;
            #(BIT_NS / 2);               // middle of the start bit
            #(9 * BIT_NS);               // middle of bit slot 9: the parity bit
            par = tx;
            checks = checks + 1;
            if (par !== (^b)) begin
                failures = failures + 1;
                $display("FAIL parity: data %02h, parity bit %b, even parity needs %b", b, par, ^b);
