        nonce    = "none";
        if (!$value$plusargs("NIRMAAN_NONCE=%s", nonce))
            if (!$value$plusargs("NONCE=%s", nonce))
                if (!$value$plusargs("nonce=%s", nonce))
                    nonce = "none";
        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (4) @(negedge clk);
        check_parity(8'h00);
        check_parity(8'h01);
        check_parity(8'hA5);
        check_parity(8'h07);
        check_parity(8'hFF);
        check_parity(8'h80);
        finish_with_verdict;
    end

    initial begin
        #200000;
        checks   = checks + 1;
        failures = failures + 1;
        $display("FAIL parity: watchdog timeout");
        finish_with_verdict;
    end
endmodule
