// Repro for bucket C (frame_period_fail.log): a frame (start, 8 data, parity,
// stop) must keep busy high for exactly 11 * CLKS_PER_BIT clock cycles, so the
// stop bit lasts a full bit time. Checks only the busy duration.
`timescale 1ns / 1ps
module tb_uart_frame_length;
    localparam integer CPB    = 8;
    localparam integer CLK_NS = 10;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #(CLK_NS / 2) clk = ~clk;

    reg [8*64-1:0] nonce;
    integer        checks;
    integer        failures;
    reg            done = 1'b0;

    task finish_with_verdict;
        begin
            if (!done) begin
                done = 1'b1;
                $display("VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failures);
                $finish;
            end
        end
    endtask

    task check_frame(input [7:0] b);
        integer n;
        begin
            @(negedge clk);
            data  = b;
            start = 1'b1;
            @(posedge clk);              // frame accepted at this edge (E0)
            @(negedge clk);              // first negedge with busy high
            start = 1'b0;
            n = 0;
            while (busy && n < 1000) begin
                n = n + 1;
                @(negedge clk);
            end
            checks = checks + 1;
            if (n != 11 * CPB) begin
                failures = failures + 1;
                $display("FAIL frame_length: data %02h, busy high %0d cycles, expected %0d", b, n, 11 * CPB);
            end else
                $display("PASS frame_length: data %02h, %0d cycles", b, n);
            repeat (2 * CPB) @(negedge clk);
        end
    endtask

    initial begin
        checks   = 0;
        failures = 0;
        nonce    = "none";
        if (!$value$plusargs("NIRMAAN_NONCE=%s", nonce))
            if (!$value$plusargs("NONCE=%s", nonce))
                if (!$value$plusargs("nonce=%s", nonce))
                    nonce = "none";
        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (4) @(negedge clk);
        check_frame(8'h00);
        check_frame(8'hFF);
        check_frame(8'hA5);
        finish_with_verdict;
    end

    initial begin
        #200000;
        checks   = checks + 1;
        failures = failures + 1;
        $display("FAIL frame_length: watchdog timeout");
        finish_with_verdict;
    end
endmodule
=== END FILE ===

