            if (!found && $value$plusargs("NIRMAAN_NONCE=%s", nonce)) found = 1'b1;
            if (!found && $value$plusargs("nirmaan_nonce=%s", nonce)) found = 1'b1;
            if (!found && $value$plusargs("NONCE=%s", nonce))         found = 1'b1;
            if (!found && $value$plusargs("nonce=%s", nonce))         found = 1'b1;
            if (!found && $value$plusargs("VERDICT_NONCE=%s", nonce)) found = 1'b1;
            if (!found && $value$plusargs("verdict_nonce=%s", nonce)) found = 1'b1;
            if (!found && $value$plusargs("RUN_NONCE=%s", nonce))     found = 1'b1;
            if (!found && $value$plusargs("run_nonce=%s", nonce))     found = 1'b1;
            if (!found && $value$plusargs("TB_NONCE=%s", nonce))      found = 1'b1;
            if (!found && $value$plusargs("SIM_NONCE=%s", nonce))     found = 1'b1;
            if (!found) nonce = "none";
        end
    endtask

    task finish_with_verdict;
        begin
            if (!done) begin
                done = 1'b1;
                $display("VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failures);
                $finish;
            end
        end
    endtask

    task check_parity(input [7:0] b);
        reg par;
        begin
            @(negedge clk);
            data  = b;
            start = 1'b1;
            @(posedge clk);              // frame accepted at this edge (E0)
            @(negedge clk);              // E0 + CLK/2
            start = 1'b0;
            #(BIT_NS / 2);               // middle of the start bit
            #(9 * BIT_NS);               // middle of bit slot 9: the parity bit
            par = tx;
            checks = checks + 1;
            if (par !== (^b)) begin
                failures = failures + 1;
                $display("FAIL parity: data %02h, parity bit %b, even parity needs %b", b, par, ^b);
            end else
                $display("PASS parity: %02h -> %b", b, par);
            wait (!busy);
            repeat (2 * CPB) @(negedge clk);
        end
    endtask

    initial begin
        checks   = 0;
        failures = 0;
        get_nonce;
        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (4) @(negedge clk);
        check_parity(8'h00);
        check_parity(8'h01);
        check_parity(8'hA5);
        check_parity(8'h07);
        check_parity(8'hFF);
        check_parity(8'h80);
        finish_with_verdict;
    end

    initial begin
        #200000;
        checks   = checks + 1;
        failures = failures + 1;
        $display("FAIL parity: watchdog timeout");
        finish_with_verdict;
    end
endmodule
